"""Individually authored explanations, settings and recovery notes for every command."""
DETAILS={}
def rows(text):
    for line in text.strip().splitlines():
        ident,basics,explain,controls,problem=line.split('|')
        DETAILS[ident]={'basics':basics.split(','),'explain':explain,'controls':controls.split('；'),'problem':problem.split('；')}

